            <li class="stage-option"><span class="stage-option__letter">B</span><span class="stage-option__title">Tile</span></li>
            <li class="stage-option"><span class="stage-option__letter">C</span><span class="stage-option__title">Tile</span></li>
          </ol>
        </div>
      </div>
    </section>
  </div>

  <!-- Frame: Phone -->
  <h2>Phone</h2>
  <p class="sg-note">One column, big tap targets. A status bar below the choices gives feedback.</p>
