cd /app && cat > src/model.rs <<'EOF'
use rusqlite::{Connection, OptionalExtension, params};
use serde::Serialize;
use std::collections::HashMap;

pub type Form = HashMap<String, String>;

#[derive(Debug, Serialize)]
pub struct Quiz {
    pub id: i64,
    pub title: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct Choice {
    pub text: String,
    pub correct: bool,
}

#[derive(Debug, Serialize)]
pub struct Question {
    pub id: i64,
    pub text: String,
    pub active: bool,
    pub options: Vec<Choice>,
}

pub struct Draft {
    pub text: String,
    pub active: bool,
    pub options: Vec<Choice>,
}

impl Draft {
    pub fn new() -> Self {
        Self { text: String::new(), active: true, options: vec![Choice { text: String::new(), correct: false }; 4] }
    }

    pub fn from_form(form: &Form) -> Self {
        let mut rows: Vec<_> = form.keys().filter_map(|k| k.strip_prefix("option_")?.parse::<usize>().ok()).collect();
        rows.sort_unstable();
        let options = rows.into_iter().map(|i| Choice {
            text: form.get(&format!("option_{i}")).cloned().unwrap_or_default(),
            correct: form.contains_key(&format!("correct_{i}")),
        }).collect();
        Self { text: form.get("question").cloned().unwrap_or_default(), active: form.contains_key("active"), options }
    }

    pub fn errors(&self) -> Vec<&'static str> {
        let mut errors = vec![];
        if self.text.trim().is_empty() { errors.push("Question is required"); }
        let options: Vec<_> = self.options.iter().filter(|o| !o.text.trim().is_empty()).collect();
        if options.len() < 2 { errors.push("Add at least two options"); }
        if !options.iter().any(|o| o.correct) { errors.push("Mark at least one option as correct"); }
        errors
    }
}

pub fn initialize(db: &Connection) -> rusqlite::Result<()> {
    db.busy_timeout(std::time::Duration::from_secs(5))?;
    db.execute_batch("PRAGMA foreign_keys = ON;
        PRAGMA journal_mode = WAL;
        CREATE TABLE IF NOT EXISTS quizzes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL CHECK(length(trim(title)) > 0)
        );
        CREATE TABLE IF NOT EXISTS questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
            text TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            position INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS questions_order ON questions(quiz_id, position);
        CREATE TABLE IF NOT EXISTS options (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            text TEXT NOT NULL,
            correct INTEGER NOT NULL,
            position INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS options_order ON options(question_id, position);")
}

pub fn quizzes(db: &Connection) -> rusqlite::Result<Vec<(Quiz, i64)>> {
    db.prepare("SELECT q.id, q.title, count(questions.id) FROM quizzes q LEFT JOIN questions ON questions.quiz_id=q.id GROUP BY q.id ORDER BY q.id DESC")?
        .query_map([], |r| Ok((Quiz { id: r.get(0)?, title: r.get(1)? }, r.get(2)?)))?.collect()
}

pub fn quiz(db: &Connection, id: i64) -> rusqlite::Result<Option<Quiz>> {
    db.query_row("SELECT id,title FROM quizzes WHERE id=?", [id], |r| Ok(Quiz { id: r.get(0)?, title: r.get(1)? })).optional()
}

pub fn questions(db: &Connection, quiz_id: i64) -> rusqlite::Result<Vec<Question>> {
    let mut result = db.prepare("SELECT id,text,active FROM questions WHERE quiz_id=? ORDER BY position,id")?
        .query_map([quiz_id], |r| Ok(Question { id: r.get(0)?, text: r.get(1)?, active: r.get(2)?, options: vec![] }))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    for q in &mut result {
        q.options = db.prepare("SELECT text,correct FROM options WHERE question_id=? ORDER BY position,id")?
            .query_map([q.id], |r| Ok(Choice { text: r.get(0)?, correct: r.get(1)? }))?.collect::<rusqlite::Result<_>>()?;
    }
    Ok(result)
}

/// The caller validates the draft first; all writes, including replacement options, are atomic.
pub fn save_question(db: &mut Connection, quiz_id: i64, question_id: Option<i64>, draft: &Draft) -> rusqlite::Result<()> {
    let tx = db.transaction()?;
    let id = if let Some(id) = question_id {
        tx.execute("UPDATE questions SET text=?,active=? WHERE id=? AND quiz_id=?", params![draft.text.trim(), draft.active, id, quiz_id])?;
        tx.execute("DELETE FROM options WHERE question_id=?", [id])?;
        id
    } else {
        tx.execute("INSERT INTO questions(quiz_id,text,active,position) VALUES(?,?,?,(SELECT coalesce(max(position),0)+1 FROM questions WHERE quiz_id=?))", params![quiz_id, draft.text.trim(), draft.active, quiz_id])?;
        tx.last_insert_rowid()
    };
    for (i, option) in draft.options.iter().filter(|o| !o.text.trim().is_empty()).enumerate() {
        tx.execute("INSERT INTO options(question_id,text,correct,position) VALUES(?,?,?,?)", params![id, option.text.trim(), option.correct, i as i64])?;
    }
    tx.commit()
}

pub fn move_question(db: &mut Connection, quiz_id: i64, question_id: i64, up: bool) -> rusqlite::Result<()> {
    let tx = db.transaction()?;
    let ids: Vec<i64> = tx.prepare("SELECT id FROM questions WHERE quiz_id=? ORDER BY position,id")?
        .query_map([quiz_id], |r| r.get(0))?.collect::<rusqlite::Result<_>>()?;
    if let Some(index) = ids.iter().position(|id| *id == question_id) {
        let neighbor = if up { index.checked_sub(1) } else { index.checked_add(1).filter(|i| *i < ids.len()) };
        if let Some(neighbor) = neighbor {
            let mut ids = ids;
            ids.swap(index, neighbor);
            for (position, id) in ids.iter().enumerate() {
                tx.execute("UPDATE questions SET position=? WHERE id=?", params![position as i64, id])?;
            }
        }
    }
    tx.commit()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn ignores_empty_correct_rows() {
        let mut d = Draft::new();
        d.text = "Question".into();
        d.options[0] = Choice { text: "one".into(), correct: false };
        d.options[1] = Choice { text: "two".into(), correct: false };
        d.options[2] = Choice { text: "  ".into(), correct: true };
        assert_eq!(d.errors(), vec!["Mark at least one option as correct"]);
        d.options[0].correct = true;
        assert!(d.errors().is_empty());
    }
    #[test]
    fn order_and_cascades() {
        let mut db = Connection::open_in_memory().unwrap();
        initialize(&db).unwrap();
        db.execute("INSERT INTO quizzes(title) VALUES ('Test')", []).unwrap();
        let mut d = Draft::new();
        d.text = "first".into();
        d.options[0] = Choice { text: "yes".into(), correct: true };
        d.options[1] = Choice { text: "no".into(), correct: false };
        save_question(&mut db, 1, None, &d).unwrap();
        d.text = "second".into();
        save_question(&mut db, 1, None, &d).unwrap();
        move_question(&mut db, 1, 2, true).unwrap();
        assert_eq!(questions(&db, 1).unwrap()[0].text, "second");
        move_question(&mut db, 1, 2, true).unwrap();
        assert_eq!(questions(&db, 1).unwrap()[0].text, "second");
        db.execute("DELETE FROM quizzes WHERE id=1", []).unwrap();
        assert!(questions(&db, 1).unwrap().is_empty());
        assert_eq!(db.query_row("SELECT count(*) FROM options", [], |r| r.get::<_, i64>(0)).unwrap(), 0);
    }
}
