mod model;
mod views;

use axum::{Router, body::to_bytes, extract::{Request, State}, http::{StatusCode, header}, response::{Html, IntoResponse, Redirect, Response}};
use base64::{Engine, engine::general_purpose::STANDARD};
use hmac::{Hmac, Mac};
use model::{Draft, Form};
use rusqlite::{Connection, params};
use sha2::Sha256;
use std::sync::{Arc, Mutex};
use subtle::ConstantTimeEq;

type App = Arc<AppState>;
struct AppState {
    db: Mutex<Connection>,
    auth: Vec<u8>,
    csrf: String,
}

#[tokio::main]
async fn main() {
    let required = |key| std::env::var(key).ok().filter(|s| !s.is_empty()).unwrap_or_else(|| panic!("{key} must be set and nonempty"));
    let username = required("QUIZZY_MODERATOR_USERNAME");
    let password = required("QUIZZY_MODERATOR_PASSWORD");
    let secret = required("SECRET_KEY_BASE");
    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes()).expect("valid HMAC key");
    mac.update(b"quizzy-moderator-csrf-v1:");
    mac.update(username.as_bytes());
    let csrf = STANDARD.encode(mac.finalize().into_bytes());
    std::fs::create_dir_all("storage").expect("create storage directory");
    let db = Connection::open("storage/quizzy.sqlite3").expect("open SQLite database");
    model::initialize(&db).expect("initialize database");
    let app = Arc::new(AppState { db: Mutex::new(db), auth: format!("{username}:{password}").into_bytes(), csrf });
    let router = Router::new().fallback(handle).with_state(app);
    let port = std::env::var("PORT").unwrap_or("3000".into()).parse::<u16>().expect("PORT must be a valid port");
    let listener = tokio::net::TcpListener::bind((std::net::Ipv4Addr::UNSPECIFIED, port)).await.expect("bind HTTP listener");
    println!("Quizzy ready on http://0.0.0.0:{port}");
    axum::serve(listener, router).with_graceful_shutdown(async {
        let mut term = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("SIGTERM handler");
        tokio::select! { _ = tokio::signal::ctrl_c() => {}, _ = term.recv() => {} }
    }).await.expect("serve HTTP");
}

async fn handle(State(app): State<App>, req: Request) -> Response {
    let mut response = handle_inner(app, req).await;
    let headers = response.headers_mut();
    headers.insert(header::CACHE_CONTROL, "no-store".parse().unwrap());
    headers.insert(header::X_CONTENT_TYPE_OPTIONS, "nosniff".parse().unwrap());
    headers.insert(header::CONTENT_SECURITY_POLICY, "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'".parse().unwrap());
    response
}

async fn handle_inner(app: App, req: Request) -> Response {
    let path = req.uri().path().trim_end_matches('/').to_string();
    let method = req.method().as_str().to_string();
    let is_read = method == "GET" || method == "HEAD";
    if path == "/up" && is_read { return (StatusCode::OK, "OK").into_response(); }
    if path.is_empty() && is_read { return Redirect::to("/moderate").into_response(); }
    if path.starts_with("/assets/") && is_read {
        let asset: Option<(&str, &'static [u8])> = match path.as_str() {
            "/assets/quizzy.css" => Some(("text/css; charset=utf-8", include_bytes!("../assets/quizzy.css"))),
            "/assets/app.css" => Some(("text/css; charset=utf-8", include_bytes!("../assets/app.css"))),
            "/assets/app.js" => Some(("text/javascript; charset=utf-8", include_bytes!("../assets/app.js"))),
            "/assets/Inter-latin.woff2" => Some(("font/woff2", include_bytes!("../assets/Inter-latin.woff2"))),
            _ => None,
        };
        return asset.map(|(mime, data)| ([(header::CONTENT_TYPE, mime)], data).into_response()).unwrap_or_else(not_found);
    }
    if path != "/moderate" && !path.starts_with("/moderate/") { return not_found(); }
    let credentials = req.headers().get(header::AUTHORIZATION).and_then(|v| v.to_str().ok()).and_then(|v| {
        let (scheme, value) = v.split_once(' ')?;
        if !scheme.eq_ignore_ascii_case("basic") { return None; }
        STANDARD.decode(value).ok()
    });
    if !credentials.is_some_and(|c| bool::from(c.as_slice().ct_eq(app.auth.as_slice()))) {
        return (StatusCode::UNAUTHORIZED, [(header::WWW_AUTHENTICATE, "Basic realm=\"Quizzy Moderator\", charset=\"UTF-8\"")], "Moderator authentication required").into_response();
    }
    if !is_read && method != "POST" { return StatusCode::METHOD_NOT_ALLOWED.into_response(); }
    let form = if method == "POST" {
        let body = match to_bytes(req.into_body(), 2 * 1024 * 1024).await {
            Ok(b) => b,
            Err(_) => return (StatusCode::PAYLOAD_TOO_LARGE, "Form is too large").into_response(),
        };
        let form: Form = match serde_urlencoded::from_bytes(&body) {
            Ok(form) => form,
            Err(_) => return (StatusCode::BAD_REQUEST, "Invalid form").into_response(),
        };
        if !form.get("csrf").is_some_and(|value| bool::from(value.as_bytes().ct_eq(app.csrf.as_bytes()))) {
            return (StatusCode::FORBIDDEN, "Invalid form token. Reload the page and try again.").into_response();
        }
        form
    } else { Form::new() };
    // SQLite operations run on a blocking worker, never on an async runtime worker.
    match tokio::task::spawn_blocking(move || {
        let mut db = app.db.lock().expect("database lock");
        dispatch(&mut db, &path, if is_read { "GET" } else { "POST" }, &form, &app.csrf)
    }).await {
        Ok(Ok(response)) => response,
        error => {
            eprintln!("Request failed: {error:?}");
            (StatusCode::INTERNAL_SERVER_ERROR, "Something went wrong. Please try again.").into_response()
        }
    }
}

fn not_found() -> Response { (StatusCode::NOT_FOUND, "Page not found").into_response() }
fn html(body: String) -> Response { Html(body).into_response() }
fn invalid(body: String) -> Response { (StatusCode::UNPROCESSABLE_ENTITY, Html(body)).into_response() }

fn dispatch(db: &mut Connection, path: &str, method: &str, form: &Form, token: &str) -> rusqlite::Result<Response> {
    let parts: Vec<_> = path.trim_start_matches('/').split('/').collect();
    if parts == ["moderate"] && method == "GET" {
        return Ok(html(views::quiz_list(&model::quizzes(db)?, token)));
    }
    if parts == ["moderate", "quizzes", "new"] && method == "GET" {
        return Ok(html(views::quiz_form(None, "", &[], token)));
    }
    if parts == ["moderate", "quizzes"] && method == "POST" {
        let title = form.get("title").map(String::as_str).unwrap_or("");
        if title.trim().is_empty() { return Ok(invalid(views::quiz_form(None, title, &["Title is required"], token))); }
        db.execute("INSERT INTO quizzes(title) VALUES (?)", [title.trim()])?;
        return Ok(Redirect::to(&format!("/moderate/quizzes/{}", db.last_insert_rowid())).into_response());
    }
    if parts.len() < 3 || parts[1] != "quizzes" { return Ok(not_found()); }
    let Some(id) = parts[2].parse::<i64>().ok() else { return Ok(not_found()); };
    let Some(quiz) = model::quiz(db, id)? else { return Ok(not_found()); };
    let url = format!("/moderate/quizzes/{id}");
    let tail = &parts[3..];
    match (method, tail) {
        ("GET", []) => Ok(html(views::quiz_page(&quiz, &model::questions(db, id)?, token))),
        ("GET", ["settings"]) => Ok(html(views::quiz_form(Some(&quiz), &quiz.title, &[], token))),
        ("POST", []) => {
            let title = form.get("title").map(String::as_str).unwrap_or("");
            if title.trim().is_empty() { return Ok(invalid(views::quiz_form(Some(&quiz), title, &["Title is required"], token))); }
            db.execute("UPDATE quizzes SET title=? WHERE id=?", params![title.trim(), id])?;
            Ok(Redirect::to(&url).into_response())
        }
        ("POST", ["delete"]) => {
            db.execute("DELETE FROM quizzes WHERE id=?", [id])?;
            Ok(Redirect::to("/moderate").into_response())
        }
        ("GET", ["preview"]) => Ok(html(views::preview(&quiz, &model::questions(db, id)?, token))),
        ("GET", ["questions", "new"]) => Ok(html(views::question_form(&quiz, None, &Draft::new(), &[], token))),
        ("POST", ["questions"]) => {
            let draft = Draft::from_form(form);
            let errors = draft.errors();
            if !errors.is_empty() { return Ok(invalid(views::question_form(&quiz, None, &draft, &errors, token))); }
            model::save_question(db, id, None, &draft)?;
            Ok(Redirect::to(&url).into_response())
        }
        _ if tail.len() >= 2 && tail[0] == "questions" => {
            let Some(qid) = tail[1].parse::<i64>().ok() else { return Ok(not_found()); };
            let Some(q) = model::questions(db, id)?.into_iter().find(|q| q.id == qid) else { return Ok(not_found()); };
            match (method, &tail[2..]) {
                ("GET", ["edit"]) => {
                    let draft = Draft { text: q.text, active: q.active, options: q.options };
                    Ok(html(views::question_form(&quiz, Some(qid), &draft, &[], token)))
                }
                ("POST", []) => {
                    let draft = Draft::from_form(form);
                    let errors = draft.errors();
                    if !errors.is_empty() { return Ok(invalid(views::question_form(&quiz, Some(qid), &draft, &errors, token))); }
                    model::save_question(db, id, Some(qid), &draft)?;
                    Ok(Redirect::to(&url).into_response())
                }
                ("POST", ["delete"]) => {
                    db.execute("DELETE FROM questions WHERE id=? AND quiz_id=?", params![qid, id])?;
                    Ok(Redirect::to(&url).into_response())
                }
                ("POST", ["active"]) => {
                    db.execute("UPDATE questions SET active=? WHERE id=? AND quiz_id=?", params![form.contains_key("active"), qid, id])?;
                    if form.contains_key("ajax") { Ok(StatusCode::NO_CONTENT.into_response()) }
                    else { Ok(Redirect::to(&url).into_response()) }
                }
                ("POST", [action @ ("move-up" | "move-down")]) => {
                    model::move_question(db, id, qid, *action == "move-up")?;
                    Ok(Redirect::to(&format!("{url}#question-{qid}")).into_response())
                }
                _ => Ok(not_found()),
            }
        }
        _ => Ok(not_found()),
    }
}
