'use strict';

// Destructive actions always use the browser's own confirmation dialog.
document.querySelectorAll('form[data-confirm]').forEach(form => {
  form.addEventListener('submit', event => {
    if (!window.confirm(form.dataset.confirm)) event.preventDefault();
  });
});

const rows = document.getElementById('option-rows');
if (rows) {
  document.getElementById('add-option').addEventListener('click', () => {
    const n = rows.children.length + 1;
    const row = document.createElement('div');
    row.className = 'option-row';
    row.innerHTML = `<input class="input" type="text" name="option_${n}" aria-label="Option ${n}" placeholder="Option ${n}" aria-describedby="options-hint"><label class="checkbox"><input type="checkbox" name="correct_${n}" value="1" aria-label="Option ${n} is correct"> Correct</label><button type="button" class="btn btn--danger btn--icon" data-clear-option aria-label="Clear option ${n}" title="Clear option ${n}">✕</button>`;
    rows.append(row);
    row.querySelector('input').focus();
  });
  rows.addEventListener('click', event => {
    const clear = event.target.closest('[data-clear-option]');
    if (!clear) return;
    const row = clear.closest('.option-row');
    row.querySelector('input[type=text]').value = '';
    row.querySelector('input[type=checkbox]').checked = false;
    row.querySelector('input').focus();
  });
}

document.querySelectorAll('[data-save-active]').forEach(input => {
  input.addEventListener('change', async () => {
    const data = new URLSearchParams(new FormData(input.form));
    data.set('ajax', '1');
    input.disabled = true;
    const status = document.getElementById('save-status');
    status.textContent = 'Saving…';
    try {
      const response = await fetch(input.form.action, { method: 'POST', body: data });
      if (!response.ok) throw new Error('Save failed');
      input.closest('.question-item').classList.toggle('question-item--inactive', !input.checked);
      let active = 0;
      document.querySelectorAll('.question-item').forEach(item => {
        item.querySelector('.question-item__num').textContent = item.querySelector('[data-save-active]').checked ? String(++active) : '—';
      });
      document.getElementById('active-count').textContent = active;
      status.textContent = '';
    } catch (_) {
      input.checked = !input.checked;
      status.textContent = 'Could not save Active. Please try again.';
    } finally {
      input.disabled = false;
    }
  });
});

// Preview is deliberately ephemeral: no fetch, cookies, local/session storage, or answer writes.
const previewData = document.getElementById('preview-data');
if (previewData) {
  const questions = JSON.parse(previewData.textContent);
  const container = document.getElementById('preview');
  let index = 0;
  let score = 0;
  let answered = false;
  const element = (tag, className, text) => {
    const el = document.createElement(tag);
    el.className = className;
    if (text !== undefined) el.textContent = text;
    return el;
  };
  function showQuestion() {
    answered = false;
    container.replaceChildren();
    if (!questions.length) {
      container.append(element('h1', 'play-question__body', 'No active questions'), element('p', '', 'Activate a question on the quiz page to try your preview.'));
      return;
    }
    const question = questions[index];
    container.append(element('div', 'play-question__num', `Question ${index + 1} of ${questions.length}`), element('h1', 'play-question__body', question.text));
    const options = element('div', 'play-options');
    question.options.forEach((option, i) => {
      const button = element('button', 'play-option');
      button.type = 'button';
      const letter = element('span', 'play-option__letter', i < 26 ? String.fromCharCode(65 + i) : String(i + 1));
      letter.setAttribute('aria-hidden', 'true');
      button.append(letter, element('span', 'play-option__title', option.text));
      button.addEventListener('click', () => answer(i));
      options.append(button);
    });
    container.append(options);
  }
  function answer(picked) {
    if (answered) return;
    answered = true;
    const question = questions[index];
    const correct = question.options[picked].correct;
    if (correct) score++;
    container.querySelectorAll('.play-option').forEach((button, i) => {
      button.disabled = true;
      if (question.options[i].correct) button.classList.add('is-correct');
      if (i === picked) {
        button.classList.add(correct ? 'is-picked' : 'is-wrong');
        button.setAttribute('aria-pressed', 'true');
      }
    });
    const status = element('div', `play-status ${correct ? 'play-status--correct' : 'play-status--wrong'}`, correct ? 'Correct!' : 'Wrong!');
    status.setAttribute('role', 'status');
    const reveal = element('div', 'preview-correct');
    reveal.append(element('strong', '', 'Correct options:'));
    const correctList = element('ul', '');
    question.options.filter(o => o.correct).forEach(o => correctList.append(element('li', '', o.text)));
    reveal.append(correctList);
    const next = element('button', 'btn btn--pink preview-next', index + 1 < questions.length ? 'Next question' : 'See score');
    next.type = 'button';
    next.addEventListener('click', () => {
      if (++index < questions.length) showQuestion();
      else {
        container.replaceChildren(element('div', 'play-question__num', 'Preview complete'), element('h1', 'play-title preview-result', `Score: ${score}/${questions.length}`), element('p', 'play-lead', 'Ready for your audience?'));
      }
    });
    container.append(status, reveal, next);
  }
  document.getElementById('start-over').addEventListener('click', () => { index = 0; score = 0; showQuestion(); });
  showQuestion();
}
